    private val byId = mapOf("discord" to DISCORD, "youtube" to YOUTUBE, "reddit" to REDDIT, "telegram" to TELEGRAM)

    /** SVG path data of a community link id (CommunityLinks), null for an unknown id. */
    fun path(id: String): String? = byId[id]

    /**
     * Icon tile like the stalzone.com footer: a fixed-size square (.community-icon-tile: dark fill, 1px border, CSS
     * sizes it) with the glyph (.community-glyph, cream fill) scaled uniformly so its longer side is [glyphSize] px,
     * centred by its real (scaled) bounds: the SVGPath sits in a Group, whose layout bounds include the scale.
     */
    fun tile(id: String, glyphSize: Double): StackPane {
        val glyph = SVGPath().apply {
            content = path(id) ?: ""
            styleClass += "community-glyph"
        }
        val b = glyph.layoutBounds
        val longest = maxOf(b.width, b.height)
        if (longest > 0) {
            glyph.scaleX = glyphSize / longest
            glyph.scaleY = glyphSize / longest
        }
        return StackPane(Group(glyph) as Node).apply {
            styleClass += listOf("community-icon-tile", "zone-radius-sm")
            isMouseTransparent = true
        }
    }
}
